const CACHE='zero-red-browser-features-v7';
const ASSETS=['./','index.html','style.css','core.js','app.js','browser-tools.js','downloads.js','settings-tools.js','media-controls.js','storage.js','reading-core.js','reader.js','sample.mp4','vendor/pdf.mjs','vendor/pdf.worker.mjs','vendor/mammoth.browser.min.js'];
const URLS=new Set(ASSETS.map(path=>new URL(path,self.registration.scope).href));
self.addEventListener('install',event=>event.waitUntil((async()=>{const cache=await caches.open(CACHE);await cache.addAll(ASSETS.map(path=>new URL(path,self.registration.scope).href));await self.skipWaiting()})()));
self.addEventListener('activate',event=>event.waitUntil((async()=>{const keys=await caches.keys();await Promise.all(keys.filter(key=>key.startsWith('zero-red-')&&key!==CACHE).map(key=>caches.delete(key)));await self.clients.claim()})()));
self.addEventListener('fetch',event=>{const request=event.request;if(request.method!=='GET'||!URLS.has(request.url))return;event.respondWith((async()=>{const cache=await caches.open(CACHE);try{const response=await fetch(request);if(response.ok&&new URL(response.url).origin===self.location.origin)await cache.put(request,response.clone());return response}catch(error){const cached=await cache.match(request);if(cached)return cached;if(request.mode==='navigate'){const home=await cache.match(new URL('./',self.registration.scope).href);if(home)return home}throw error}})())});
